declare v_old jsonb; v_new jsonb; v_club uuid; v_actor uuid:=auth.uid(); v_entity_id text; v_action text;
begin
  v_old:=case when tg_op in ('UPDATE','DELETE') then public.audit_redact_json_v1(to_jsonb(old)) else null end;
  v_new:=case when tg_op in ('INSERT','UPDATE') then public.audit_redact_json_v1(to_jsonb(new)) else null end;
  v_club:=coalesce(nullif(v_new->>'club_id','')::uuid,nullif(v_old->>'club_id','')::uuid);
  if v_club is null then if tg_op='DELETE' then return old; else return new; end if; end if;
  v_entity_id:=coalesce(v_new->>'id',v_old->>'id',v_new->>'profile_id',v_old->>'profile_id',v_new->>'member_id',v_old->>'member_id',v_new->>'permission_key',v_old->>'permission_key',v_new->>'module_code',v_old->>'module_code');
  v_action:=case tg_op when 'INSERT' then 'created' when 'UPDATE' then 'updated' when 'DELETE' then 'deleted' else lower(tg_op) end;
  insert into public.audit_log(club_id,actor_id,action,entity_type,entity_id,before_data,after_data,created_at)
  values(v_club,v_actor,v_action,tg_table_name,v_entity_id,v_old,v_new,now());
  if tg_op='DELETE' then return old; end if;
  return new;
end

declare v_actor uuid:=auth.uid();
begin
  if tg_op='INSERT' then
    new.created_at:=now();
    if v_actor is not null then new.created_by:=v_actor; new.updated_by:=v_actor; end if;
    new.updated_at:=now();
    return new;
  end if;
  new.created_at:=old.created_at;
  new.created_by:=old.created_by;
  new.updated_at:=now();
  if v_actor is not null then new.updated_by:=v_actor; else new.updated_by:=old.updated_by; end if;
  return new;
end

