declare
  v_club uuid;
begin
  if new.status is not distinct from old.status
     and new.checked_in_at is not distinct from old.checked_in_at
     and new.notes is not distinct from old.notes then
    return new;
  end if;

  select e.club_id
    into v_club
  from public.event_registrations er
  join public.events e on e.id = er.event_id
  where er.id = new.registration_id;

  if v_club is null then
    raise exception 'guest_registration_not_found' using errcode = 'P0001';
  end if;

  if not public.has_club_permission(v_club, 'manageEventParticipants') then
    raise exception 'guest_attendance_permission_denied' using errcode = '42501';
  end if;

  return new;
end;

declare
  v_event_id uuid;
  v_capacity integer;
  v_occupancy bigint;
  v_required_seats integer := 1;
begin
  if tg_table_name = 'event_registrations' then
    v_event_id := new.event_id;
    if nullif(btrim(new.guest_name), '') is not null then
      v_required_seats := 2;
    end if;
  elsif tg_table_name = 'event_registration_guests' then
    select er.event_id
      into v_event_id
    from public.event_registrations er
    where er.id = new.registration_id;

    if v_event_id is null then
      return new;
    end if;
  else
    raise exception using
      errcode = 'P0001',
      message = 'EVENT_CAPACITY_INVALID_TRIGGER';
  end if;

  select e.capacity
    into v_capacity
  from public.events e
  where e.id = v_event_id
  for update;

  if not found or v_capacity is null then
    return new;
  end if;

  select
    (
      select count(*)
      from public.event_registrations er
      where er.event_id = v_event_id
    )
    + (
      select count(*)
      from public.event_registrations er
      where er.event_id = v_event_id
        and nullif(btrim(er.guest_name), '') is not null
    )
    + (
      select count(*)
      from public.event_registration_guests g
      join public.event_registrations er on er.id = g.registration_id
      where er.event_id = v_event_id
    )
    into v_occupancy;

  if v_occupancy + v_required_seats > v_capacity then
    raise exception using
      errcode = 'P0001',
      message = 'EVENT_CAPACITY_REACHED',
      detail = format(
        'Capacidade: %s; ocupação atual: %s; lugares pedidos: %s.',
        v_capacity,
        v_occupancy,
        v_required_seats
      );
  end if;

  return new;
end;

