      from public.members m
      where m.id = old.member_id
        and m.club_id = old.club_id
    ) then
      v_label:=trim(coalesce(old.brand,'')||' '||coalesce(old.model,''));
      perform public.member_timeline_append_v1(
        old.club_id,
        old.member_id,
        'motorcycle_removed',
